content:
body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
  background-color: #121212;
  color: #ffffff;
  overflow: hidden;
  user-select: none;
}

.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  box-sizing: border-box;
}

.header {
  padding: 16px 20px;
  text-align: center;
  background-color: rgba(24, 24, 27, 0.8);
  backdrop-filter: blur(8px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 10;
}

.title {
  margin: 0 0 6px 0;
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #f43f5e;
}

.instruction {
  margin: 0;
  font-size: 0.9rem;
  color: #a1a1aa;
}

.canvas-container {
  flex: 1;
  width: 100%;
  position: relative;
  overflow: hidden;
  cursor: grab;
  background: radial-gradient(circle at center, #27272a 0%, #09090b 100%);
}

.canvas-container:active {
  cursor: grabbing;
}

.controls-panel {
  padding: 16px 20px;
  display: flex;
  justify-content: center;
  gap: 12px;
  background-color: rgba(24, 24, 27, 0.8);
  backdrop-filter: blur(8px);
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  z-index: 10;
}

.btn {
  background-color: #f43f5e;
  color: white;
  border: none;
  padding: 10px 20px;
  font-size: 0.95rem;
  font-weight: 600;
  border-radius: 8px;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s, box-shadow 0.2s;
  box-shadow: 0 4px 12px rgba(244, 63, 94, 0.3);
}

.btn:hover {
  background-color: #e11d48;
  box-shadow: 0 6px 16px rgba(244, 63, 94, 0.4);
}

.btn:active {
  transform: scale(0.97);
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import './index.css';

export default function App() {
  const mountRef = useRef<HTMLDivElement>(null);
  const cubeRef = useRef<THREE.Mesh | null>(null);
  const isDraggingRef = useRef(false);
  const previousMousePositionRef = useRef({ x: 0, y: 0 });
  const rotationDampingRef = useRef({ x: 0.005, y: 0.005 });

  const handleReset = () => {
    if (cubeRef.current) {
      cubeRef.current.rotation.x = 0;
      cubeRef.current.rotation.y = 0;
      rotationDampingRef.current = { x: 0.002, y: 0.005 };
    }
  };

  useEffect(() => {
    const currentMount = mountRef.current;
    if (!currentMount) return;

    // シーン作成
    const scene = new THREE.Scene();

    // カメラ作成
    const camera = new THREE.PerspectiveCamera(
      75,
      currentMount.clientWidth / currentMount.clientHeight,
      0.1,
      1000
    );
    camera.position.z = 5;

    // レンダラー作成
    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
    renderer.setSize(currentMount.clientWidth, currentMount.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    currentMount.appendChild(renderer.domElement);

    // キューブの作成（各面に異なるマテリアルを適用）
    const geometry = new THREE.BoxGeometry(2, 2, 2);
    const materials = [
      new THREE.MeshStandardMaterial({ color: 0xf43f5e, roughness: 0.3, metalness: 0.8 }), // 右
      new THREE.MeshStandardMaterial({ color: 0x3b82f6, roughness: 0.3, metalness: 0.8 }), // 左
      new THREE.MeshStandardMaterial({ color: 0x10b981, roughness: 0.3, metalness: 0.8 }), // 上
      new THREE.MeshStandardMaterial({ color: 0xf59e0b, roughness: 0.3, metalness: 0.8 }), // 下
      new THREE.MeshStandardMaterial({ color: 0x8b5cf6, roughness: 0.3, metalness: 0.8 }), // 前
      new THREE.MeshStandardMaterial({ color: 0xec4899, roughness: 0.3, metalness: 0.8 }), // 後
    ];

    const cube = new THREE.Mesh(geometry, materials);
    scene.add(cube);
    cubeRef.current = cube;

    // ライティング
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.7);
    scene.add(ambientLight);

    const pointLight = new THREE.PointLight(0xffffff, 1.5);
    pointLight.position.set(5, 5, 5);
    scene.add(pointLight);

    const pointLight2 = new THREE.PointLight(0xffffff, 0.8);
    pointLight2.position.set(-5, -5, -5);
    scene.add(pointLight2);

    // マウス・タッチ操作ハンドラー
    const onMouseDown = (e: MouseEvent) => {
      isDraggingRef.current = true;
      previousMousePositionRef.current = { x: e.clientX, y: e.clientY };
    };

    const onMouseMove = (e: MouseEvent) => {
      if (!isDraggingRef.current || !cubeRef.current) return;

      const deltaX = e.clientX - previousMousePositionRef.current.x;
      const deltaY = e.clientY - previousMousePositionRef.current.y;

      cubeRef.current.rotation.y += deltaX * 0.01;
      cubeRef.current.rotation.x += deltaY * 0.01;

      rotationDampingRef.current = {
        x: deltaY * 0.001,
        y: deltaX * 0.001,
      };

      previousMousePositionRef.current = { x: e.clientX, y: e.clientY };
    };

    const onMouseUp = () => {
      isDraggingRef.current = false;
    };

    const onTouchStart = (e: TouchEvent) => {
      if (e.touches.length === 1) {
        isDraggingRef.current = true;
        previousMousePositionRef.current = {
          x: e.touches[0].clientX,
          y: e.touches[0].clientY,
        };
      }
    };

    const onTouchMove = (e: TouchEvent) => {
      if (!isDraggingRef.current || !cubeRef.current || e.touches.length !== 1) return;

      const deltaX = e.touches[0].clientX - previousMousePositionRef.current.x;
      const deltaY = e.touches[0].clientY - previousMousePositionRef.current.y;

      cubeRef.current.rotation.y += deltaX * 0.01;
      cubeRef.current.rotation.x += deltaY * 0.01;

      rotationDampingRef.current = {
        x: deltaY * 0.001,
        y: deltaX * 0.001,
      };

      previousMousePositionRef.current = {
        x: e.touches[0].clientX,
        y: e.touches[0].clientY,
      };
    };

    const onTouchEnd = () => {
      isDraggingRef.current = false;
    };

    currentMount.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);

    currentMount.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchmove', onTouchMove, { passive: true });
    window.addEventListener('touchend', onTouchEnd);

    // リサイズ対応
    const handleResize = () => {
      if (!currentMount) return;
      camera.aspect = currentMount.clientWidth / currentMount.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(currentMount.clientWidth, currentMount.clientHeight);
    };

    window.addEventListener('resize', handleResize);

    // アニメーションループ
    let animationFrameId: number;
    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      if (!isDraggingRef.current && cubeRef.current) {
        cubeRef.current.rotation.x += rotationDampingRef.current.x;
        cubeRef.current.rotation.y += rotationDampingRef.current.y;

        // 慣性の減衰
        rotationDampingRef.current.x *= 0.95;
        rotationDampingRef.current.y *= 0.95;

        // 完全に停止せず緩やかに回転し続ける
        if (
          Math.abs(rotationDampingRef.current.x) < 0.0001 &&
          Math.abs(rotationDampingRef.current.y) < 0.0001
        ) {
          cubeRef.current.rotation.y += 0.003;
        }
      }

      renderer.render(scene, camera);
    };

    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      currentMount.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
      currentMount.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onTouchEnd);

      cancelAnimationFrame(animationFrameId);
      if (currentMount && renderer.domElement) {
        currentMount.removeChild(renderer.domElement);
      }
      renderer.dispose();
    };
  }, []);

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="title">3D立方体ビューア</h1>
        <p className="instruction">マウスや指でドラッグして立方体を自由に回転させてみましょう</p>
      </header>
      <div className="canvas-container" ref={mountRef} />
      <footer className="controls-panel">
        <button className="btn" onClick={handleReset}>
          視点をリセット
        </button>
      </footer>
    </div>
  );
}
